import java.io.*;
import java.util.Scanner;

public class TryCatchFinally {
    public static void main(String[] args) {
        // === ESTRUCTURA BASICA ===
        try {
            int resultado = 10 / 0; // ArithmeticException
            System.out.println("Resultado: " + resultado);
        } catch (ArithmeticException e) {
            System.out.println("Error aritmetico: " + e.getMessage());
        } finally {
            System.out.println("Se ejecuta SIEMPRE");
        }

        // === MULTI-CATCH ===
        try {
            String texto = null;
            texto.length(); // NullPointerException
        } catch (NullPointerException | ArrayIndexOutOfBoundsException e) {
            System.out.println("Error de acceso: " + e.getClass().getSimpleName());
        }

        // === PROPAGACION CON THROWS ===
        try {
            leerArchivo("datos.txt");
        } catch (FileNotFoundException e) {
            System.out.println("No se encontro: " + e.getMessage());
        } catch (IOException e) {
            System.out.println("Error de E/S: " + e.getMessage());
        }
    }

    // Metodo que propaga la excepcion (no la captura)
    static void leerArchivo(String ruta) throws FileNotFoundException, IOException {
        try (Scanner sc = new Scanner(new File(ruta))) {
            while (sc.hasNextLine()) {
                System.out.println(sc.nextLine());
            }
        }
    }
}

public class GestionAcademicaExcepciones {

    // Metodo que lanza una excepcion checked
    public static double calcularMedia(double[] notas) throws IllegalArgumentException {
        if (notas == null || notas.length == 0) {
            throw new IllegalArgumentException("El array de notas no puede estar vacio");
        }
        double suma = 0;
        for (double nota : notas) {
            if (nota < 0 || nota > 10) {
                throw new IllegalArgumentException(
                    "Nota invalida: " + nota + ". Debe estar entre 0 y 10.");
            }
            suma += nota;
        }
        return suma / notas.length;
    }

    // Metodo que captura y relanza
    public static void procesarAlumno(String nombre, double[] notas) {
        try {
            double media = calcularMedia(notas);
            System.out.printf("%s: media = %.2f%n", nombre, media);
        } catch (IllegalArgumentException e) {
            System.out.println("Error procesando " + nombre + ": " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        procesarAlumno("Ana", new double[]{8.5, 7.0, 9.2});
        procesarAlumno("Carlos", new double[]{7.0, -1.0, 8.0}); // Nota invalida
        procesarAlumno("Maria", new double[]{});                  // Array vacio
    }
}

public class StackTraceEjemplo {

    public static void nivel3() {
        throw new RuntimeException("Error en nivel 3");
    }

    public static void nivel2() {
        nivel3(); // La excepcion se propaga
    }

    public static void nivel1() {
        nivel2(); // La excepcion se propaga
    }

    public static void main(String[] args) {
        try {
            nivel1();
        } catch (RuntimeException e) {
            // Mostrar stack trace completa
            System.out.println("Mensaje: " + e.getMessage());
            System.out.println("\nStack trace:");
            e.printStackTrace();

            // Obtener solo los elementos relevantes
            StackTraceElement[] trace = e.getStackTrace();
            System.out.println("\nElementos relevantes:");
            for (StackTraceElement elem : trace) {
                System.out.printf("  %s.%s (linea %d)%n",
                    elem.getClassName(),
                    elem.getMethodName(),
                    elem.getLineNumber());
            }
        }
    }
}

