public class SistemaNotas {
    public static double calcularMedia(String nombre, double[] notas)
            throws IllegalArgumentException {
        try {
            if (notas == null) {
                throw new IllegalArgumentException("El array de notas es null");
            }
            if (notas.length == 0) {
                throw new IllegalArgumentException("El array de notas esta vacio");
            }
            double suma = 0;
            for (double nota : notas) {
                if (nota < 0 || nota > 10) {
                    throw new IllegalArgumentException(
                        "Nota invalida: " + nota + " (debe ser 0-10)");
                }
                suma += nota;
            }
            return suma / notas.length;
        } finally {
            System.out.println("Proceso completado para: " + nombre);
        }
    }

    public static void main(String[] args) {
        String[] alumnos = {"Ana", "Carlos", "Maria"};
        double[][] notas = {
            {8.5, 7.0, 9.2},
            {7.0, -1.0, 8.0},
            {}
        };

        for (int i = 0; i < alumnos.length; i++) {
            try {
                double media = calcularMedia(alumnos[i], notas[i]);
                System.out.printf("%s: media = %.2f%n", alumnos[i], media);
            } catch (IllegalArgumentException e) {
                System.out.println("Error para " + alumnos[i] + ": " + e.getMessage());
            }
        }
    }
}

