/**
 * Excepcion que se lanza cuando se intenta asignar una nota
 * fuera del rango valido (0.0 - 10.0).
 */
public class NotaInvalidaException extends Exception {

    private final double notaInvalida;
    private final String alumno;

    /**
     * Crea una NotaInvalidaException con la nota y el alumno.
     * 
     * @param notaInvalida la nota que causo el error
     * @param alumno nombre del alumno afectado
     */
    public NotaInvalidaException(double notaInvalida, String alumno) {
        super(String.format(
            "Nota invalida: %.1f para el alumno '%s'. Debe estar entre 0.0 y 10.0.",
            notaInvalida, alumno));
        this.notaInvalida = notaInvalida;
        this.alumno = alumno;
    }

    /** Obtiene la nota que causo el error */
    public double getNotaInvalida() { return notaInvalida; }

    /** Obtiene el nombre del alumno */
    public String getAlumno() { return alumno; }
}

// Uso:
public class Alumno {
    private String nombre;
    private double notaMedia;

    public void setNotaMedia(double nota) throws NotaInvalidaException {
        if (nota < 0 || nota > 10) {
            throw new NotaInvalidaException(nota, nombre);
        }
        this.notaMedia = nota;
    }
}

/**
 * Excepcion unchecked que se lanza cuando se intenta matricular
 * en un curso que ya tiene el maximo de alumnos.
 */
public class CursoLlenoException extends RuntimeException {

    private final String curso;
    private final int capacidadMaxima;
    private final int alumnosActuales;

    public CursoLlenoException(String curso, int capacidad, int actuales) {
        super(String.format(
            "El curso '%s' esta lleno (%d/%d alumnos).",
            curso, actuales, capacidad));
        this.curso = curso;
        this.capacidadMaxima = capacidad;
        this.alumnosActuales = actuales;
    }

    public String getCurso() { return curso; }
    public int getCapacidadMaxima() { return capacidadMaxima; }
    public int getAlumnosActuales() { return alumnosActuales; }
}

// Uso:
public class Curso {
    private String nombre;
    private int capacidadMaxima;
    private List<Alumno> alumnos;

    public void matricular(Alumno alumno) {
        if (alumnos.size() >= capacidadMaxima) {
            throw new CursoLlenoException(nombre, capacidadMaxima, alumnos.size());
        }
        alumnos.add(alumno);
    }
}

import java.io.*;

/**
 * Excepcion que se lanza al procesar datos de un alumno.
 */
public class ErrorProcesamientoException extends Exception {
    public ErrorProcesamientoException(String mensaje, Throwable causa) {
        super(mensaje, causa); // Guarda la causa original
    }
}

public class ProcesadorAlumnos {

    public static void procesarArchivo(String ruta) throws ErrorProcesamientoException {
        try {
            BufferedReader reader = new BufferedReader(new FileReader(ruta));
            String linea;
            while ((linea = reader.readLine()) != null) {
                // Procesar cada linea...
            }
            reader.close();
        } catch (FileNotFoundException e) {
            // Relanzar con causa
            throw new ErrorProcesamientoException(
                "No se encontro el archivo: " + ruta, e);
        } catch (IOException e) {
            throw new ErrorProcesamientoException(
                "Error leyendo el archivo: " + ruta, e);
        } catch (Exception e) {
            throw new ErrorProcesamientoException(
                "Error procesando datos del archivo", e);
        }
    }

    public static void main(String[] args) {
        try {
            procesarArchivo("alumnos.txt");
        } catch (ErrorProcesamientoException e) {
            System.out.println("Error: " + e.getMessage());
            System.out.println("Causa original: " + e.getCause().getClass().getSimpleName());
        }
    }
}

