Antes de Java 7, para liberar recursos (archivos, conexiones, streams) se usaba `try-finally`:

```java
BufferedReader reader = null;
try {
    reader = new BufferedReader(new FileReader("datos.txt"));
    String linea = reader.readLine();
    System.out.println(linea);
} catch (IOException e) {
    e.printStackTrace();
} finally {
    if (reader != null) {
        try {
            reader.close(); // Liberar el recurso
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

**Problemas:**
1. Mucho código repetitivo y verboso.
2. Fácil olvidar cerrar el recurso (memory leak).
3. Manejo doble de excepciones: una en try, otra en finally.

La solución es **try-with-resources** (Java 7+): el recurso se cierra automáticamente.

import java.io.*;

public class TryWithResources {
    public static void main(String[] args) {

        // === ARCHIVO: leer con try-with-resources ===
        // El recurso se declara entre parentesis y se cierra automaticamente
        try (BufferedReader reader = new BufferedReader(new FileReader("datos.txt"))) {
            String linea;
            while ((linea = reader.readLine()) != null) {
                System.out.println(linea);
            }
        } catch (FileNotFoundException e) {
            System.out.println("Archivo no encontrado: " + e.getMessage());
        } catch (IOException e) {
            System.out.println("Error de lectura: " + e.getMessage());
        }
        // reader.close() se ejecuta AUTOMATICAMENTE al salir del try

        // === ESCRIBIR con try-with-resources ===
        try (BufferedWriter writer = new BufferedWriter(new FileWriter("resultado.txt"))) {
            writer.write("Primera linea");
            writer.newLine();
            writer.write("Segunda linea");
            writer.newLine();
            writer.write("Tercera linea");
        } catch (IOException e) {
            System.out.println("Error de escritura: " + e.getMessage());
        }

        // === MULTIPLES recursos ===
        try (BufferedReader reader = new BufferedReader(new FileReader("entrada.txt"));
             BufferedWriter writer = new BufferedWriter(new FileWriter("salida.txt"))) {

            String linea;
            while ((linea = reader.readLine()) != null) {
                writer.write(linea.toUpperCase());
                writer.newLine();
            }
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

/**
 * Clase que representa una conexion simulada a una base de datos.
 * Implementa AutoCloseable para poder usarse en try-with-resources.
 */
public class ConexionBD implements AutoCloseable {
    private String url;
    private boolean conectada;

    public ConexionBD(String url) {
        this.url = url;
        this.conectada = true;
        System.out.println("Conexion abierta a: " + url);
    }

    public void ejecutarConsulta(String sql) {
        if (!conectada) {
            throw new IllegalStateException("Conexion cerrada");
        }
        System.out.println("Ejecutando: " + sql);
    }

    /**
     * Cierra la conexion. Se ejecuta automaticamente en try-with-resources.
     */
    @Override
    public void close() {
        if (conectada) {
            conectada = false;
            System.out.println("Conexion cerrada: " + url);
        }
    }
}

// Uso:
public class EjemploConexion {
    public static void main(String[] args) {
        try (ConexionBD conn = new ConexionBD("jdbc:mysql://localhost:3306/mibase")) {
            conn.ejecutarConsulta("SELECT * FROM alumnos");
            conn.ejecutarConsulta("SELECT * FROM cursos");
        } // close() se ejecuta automaticamente
        System.out.println("Conexion liberada");
    }
}

/**
 * Sesion de gestion academica que puede abrirse y cerrarse.
 */
public class SesionAcademica implements AutoCloseable {
    private String id;
    private boolean abierta;
    private java.util.List<String> operaciones;

    public SesionAcademica(String id) {
        this.id = id;
        this.abierta = true;
        this.operaciones = new java.util.ArrayList<>();
        System.out.println("Sesion " + id + " abierta");
    }

    public void registrarOperacion(String operacion) {
        if (!abierta) throw new IllegalStateException("Sesion cerrada");
        operaciones.add(operacion);
        System.out.println("  [" + id + "] " + operacion);
    }

    @Override
    public void close() {
        if (abierta) {
            abierta = false;
            System.out.println("Sesion " + id + " cerrada. " +
                operaciones.size() + " operaciones registradas.");
        }
    }
}

// Uso:
public class EjemploSesion {
    public static void main(String[] args) {
        try (SesionAcademica sesion = new SesionAcademica("S001")) {
            sesion.registrarOperacion("Alumno Ana creado");
            sesion.registrarOperacion("Nota 8.5 asignada");
            sesion.registrarOperacion("Curso Programacion matriculado");
        }
        // La sesion se cierra automaticamente aqui
    }
}

