public class TemporizadorAcademico implements AutoCloseable {
    private String operacion;
    private long inicio;

    public TemporizadorAcademico(String operacion) {
        this.operacion = operacion;
        this.inicio = System.currentTimeMillis();
        System.out.println("Iniciando: " + operacion);
    }

    @Override
    public void close() {
        long fin = System.currentTimeMillis();
        long duracion = fin - inicio;
        System.out.printf("%s completada en %d ms%n", operacion, duracion);
    }

    public static void main(String[] args) {
        try (TemporizadorAcademico timer = new TemporizadorAcademico("Calcular medias")) {
            // Simular trabajo
            try {
                Thread.sleep(150);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.out.println("Hilo interrumpido");
            }
            System.out.println("Medias calculadas");
        }
        // Timer se cierra y muestra el tiempo
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class PipelineProcesamiento {
    record Resultado(String nombre, double nota, String estado) {}

    public static void main(String[] args) {
        List<Resultado> resultados = new ArrayList<>();

        // Leer notas
        try (BufferedReader reader = new BufferedReader(new FileReader("notas.txt"))) {
            String linea;
            while ((linea = reader.readLine()) != null) {
                String[] partes = linea.split(",");
                if (partes.length == 2) {
                    String nombre = partes[0].trim();
                    double nota = Double.parseDouble(partes[1].trim());
                    String estado = nota >= 5 ? "Aprobado" : "Suspensa";
                    resultados.add(new Resultado(nombre, nota, estado));
                }
            }
        } catch (IOException e) {
            System.out.println("Error leyendo: " + e.getMessage());
        }

        // Escribir resultados
        try (BufferedWriter writer = new BufferedWriter(new FileWriter("resultados.txt"))) {
            writer.write("Nombre,Nota,Estado");
            writer.newLine();
            for (Resultado r : resultados) {
                writer.write(r.nombre() + "," + r.nota() + "," + r.estado());
                writer.newLine();
            }
            System.out.println("Procesados " + resultados.size() + " registros");
        } catch (IOException e) {
            System.out.println("Error escribiendo: " + e.getMessage());
        }
    }
}
